cd /opt/nxeon && node -e '
import("./scripts/blog-seed-lib.mjs").then(m=>{
const titles=[
"How to Self-Host Nextcloud on a VPS",
"How to Set Up a WireGuard VPN on a VPS",
"How to Self-Host Grafana and Prometheus for Monitoring",
"How to Self-Host a Matrix/Synapse Chat Server",
"12 Best Self-Hosted Apps to Run on a VPS"
];
titles.forEach(t=>console.log(m.slugify(t)));
m.db.$disconnect();
});
'

cd /opt/nxeon && node -e '
import("./scripts/blog-seed-lib.mjs").then(async(m)=>{
  const rows = await m.db.blogPost.findMany({where:{tags:{has:"seobatch"}}, select:{slug:true,title:true,body:true,seoTitle:true,seoDescription:true}});
  const mine = rows.filter(r=>r.slug.includes("self-host")||r.slug.includes("wireguard-vpn-server")||r.slug.includes("openvpn")||r.slug.includes("best-self-hosted"));
  let warn=0;
  for(const r of mine){
    const words = r.body.trim().split(/\s+/).length;
    const links = (r.body.match(/\]\(\//g)||[]).length;
    const shots = (r.body.match(/\{\{SCREENSHOT\}\}/g)||[]).length;
    const st=r.seoTitle.length, sd=r.seoDescription.length;
    const flags=[];
    if(words<1000||words>1600) flags.push("WORDS:"+words);
    if(links<3||links>7) flags.push("LINKS:"+links);
    if(shots<1||shots>2) flags.push("SHOTS:"+shots);
    if(st>60) flags.push("SEOTITLE:"+st);
    if(sd>155) flags.push("SEODESC:"+sd);
    if(flags.length){warn++; console.log("FLAG", r.slug, flags.join(" "));}
  }
  console.log("total mine:", mine.length, "flagged:", warn);
  // stats
  const w = mine.map(r=>r.body.trim().split(/\s+/).length);
  console.log("word range:", Math.min(...w), "-", Math.max(...w));
  await m.db.$disconnect();
});
'

